#include <bits/stdc++.h>
using namespace std;

const int INF = 1000000000;

struct DSU {
    vector<int> p, r;
    DSU(int n) : p(n + 1), r(n + 1, 0) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, B;
    cin >> N >> B;

    vector<tuple<int, int, int>> edges;
    edges.reserve(B);

    for (int i = 0; i < B; i++) {
        int I, J, P;
        cin >> I >> J >> P;
        edges.emplace_back(P, I, J);
    }

    sort(edges.begin(), edges.end(), [](const auto& a, const auto& b) {
        return get<0>(a) > get<0>(b);
    });

    DSU dsu(N);
    vector<vector<pair<int, int>>> adj(N + 1);

    for (auto [P, I, J] : edges) {
        if (dsu.unite(I, J)) {
            adj[I].push_back({J, P});
            adj[J].push_back({I, P});
        }
    }

    int LOG = 1;
    while ((1 << LOG) <= N) LOG++;
    LOG++;

    vector<vector<int>> up(LOG, vector<int>(N + 1));
    vector<vector<int>> mn(LOG, vector<int>(N + 1, INF));
    vector<int> depth(N + 1, 0);
    vector<char> vis(N + 1, 0);

    queue<int> q;
    q.push(1);
    vis[1] = 1;
    up[0][1] = 1;
    mn[0][1] = INF;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (auto [v, w] : adj[u]) {
            if (!vis[v]) {
                vis[v] = 1;
                depth[v] = depth[u] + 1;
                up[0][v] = u;
                mn[0][v] = w;
                q.push(v);
            }
        }
    }

    for (int k = 1; k < LOG; k++) {
        for (int v = 1; v <= N; v++) {
            int anc = up[k - 1][v];
            up[k][v] = up[k - 1][anc];
            mn[k][v] = min(mn[k - 1][v], mn[k - 1][anc]);
        }
    }

    int C;
    cin >> C;

    while (C--) {
        int X, Y;
        cin >> X >> Y;

        int u = X, v = Y;
        int ans = INF;

        if (depth[u] < depth[v]) swap(u, v);

        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) {
            if (diff & (1 << k)) {
                ans = min(ans, mn[k][u]);
                u = up[k][u];
            }
        }

        if (u != v) {
            for (int k = LOG - 1; k >= 0; k--) {
                if (up[k][u] != up[k][v]) {
                    ans = min(ans, mn[k][u]);
                    ans = min(ans, mn[k][v]);
                    u = up[k][u];
                    v = up[k][v];
                }
            }
            ans = min(ans, mn[0][u]);
            ans = min(ans, mn[0][v]);
        }

        cout << ans << '\n';
    }

    return 0;
}
